import bpy, math, mathutils
# fix roof / canopy height and depth
roof=bpy.data.objects.get("Roof")
if roof: roof.location=(0,0,2.85); roof.scale=(1,0.72,1)
# awning under roof front edge
for i in range(7):
    o=bpy.data.objects.get(f"Awning_{i}")
    if o: o.location=(o.location.x,-1.45,2.48)
# noren up a bit
for i,x in enumerate([-1.5,-0.75,0,0.75,1.5]):
    o=bpy.data.objects.get(f"Noren_{i}")
    if o: o.location=(x,-1.15,2.10)
# lanterns hang below awning
for x in [-1.8,-0.9,0,0.9,1.8]:
    s=bpy.data.objects.get(f"LanternStem_{x}")
    if s: s.location=(x,-1.25,2.30)
    l=bpy.data.objects.get(f"Lantern_{x}")
    if l: l.location=(x,-1.25,2.08)
    r=bpy.data.objects.get(f"LanternRing_{x}")
    if r: r.location=(x,-1.25,2.24)
    rb=bpy.data.objects.get(f"LanternRingB_{x}")
    if rb: rb.location=(x,-1.25,1.92)
# sign board
sb=bpy.data.objects.get("SignBoard")
if sb: sb.location=(0,-1.32,2.62)
# posts taller - scale z
for name in list(bpy.data.objects.keys()):
    if name.startswith("Post_"):
        o=bpy.data.objects[name]; o.location.z=1.35; o.scale.z=1.3
# camera frontal lower
cam=bpy.data.objects.get("HeroCam")
cam.location=(2.6,-6.2,2.0)
target=mathutils.Vector((0,0,1.35))
cam.rotation_euler=(target-cam.location).to_track_quat('-Z','Y').to_euler()
cam.data.lens=38
bpy.context.scene.camera=cam
# render
base="<vol>/dev/art-crit-runs/2026-10-16-092538-3d-octopus-ramen-shop/muse-wonder-1.0-mc-medium-20261016-092538/work"
bpy.context.scene.render.filepath=base+"/preview2.png"
bpy.context.scene.render.resolution_x=640; bpy.context.scene.render.resolution_y=480
bpy.ops.render.render(write_still=True)
result={"ok":True}
print(result)

